export function Thumbnail({
  size = {{size}},
  radius = {{radius}},
  badge = {{badge}},
  label = "{{label}}",
}) {
  return (
    <figure style={{ margin: 0, display: "inline-flex", flexDirection: "column", alignItems: "center", gap: 6,
      font: "12px/1.3 system-ui, sans-serif", color: "#241430", width: size }}>
      <span style={{ position: "relative", display: "block", overflow: "hidden", border: "1px solid #24143022",
        width: size, height: size, borderRadius: radius }}>
        <svg viewBox="0 0 48 48" width="100%" height="100%" style={{ display: "block" }} aria-hidden="true">
          <rect width="48" height="48" fill="#BFD9F2" />
          <circle cx="24" cy="24" r="12" fill="#A8E6C1" />
        </svg>
        {badge && (
          <span style={{ position: "absolute", top: -3, right: -3, width: 12, height: 12, borderRadius: "50%",
            background: "#E8A020", border: "2px solid #FAF7F2" }} aria-hidden="true" />
        )}
      </span>
      <figcaption style={{ maxWidth: 120, textAlign: "center", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
        {label}
      </figcaption>
    </figure>
  );
}
